import re
import sys
from datetime import date

SWISS = re.compile(r"([0-9]{1,2})\.([0-9]{1,2})\.([0-9]{4})")
ISO = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def plausible(y, m, d):
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    if m == 2:
        if d == 29:
            if y % 4 == 0:
                if y % 100 == 0:
                    if y % 400 == 0:
                        return True
                    return False
                return True
            return True
        return d == 28
    if m in [4, 6, 9, 11]:
        return d == 30
    return d == 31


def convert(text):
    m = SWISS.fullmatch(text)
    if m:
        d, mo, y = map(int, m.groups())
        if plausible(y, mo, d):
            return f"{y:04d}-{mo:02d}-{d:02d}"
        return "invalid"
    m = ISO.fullmatch(text)
    if m:
        y, mo, d = map(int, m.groups())
        if plausible(y, mo, d):
            return f"{d:02d}.{mo:02d}.{y:04d}"
        return "invalid"
    return "invalid"


def main():
    for line in sys.stdin:
        text = line.strip()
        if text:
            print(convert(text))


if __name__ == "__main__":
    main()
